function gen(rng){
  return OPEN[Math.floor(rng()*OPEN.length)]+' 你 '+MID[Math.floor(rng()*MID.length)]+GOOD[Math.floor(rng()*GOOD.length)]+'。';
}
var EXPORTS={gen:gen};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BlessingForgePure = EXPORTS; }
